{
  "name": "SalesTrack - Daily Reporting",
  "description": "A glassmorphism-styled PWA for sales executives to track daily sales, manage CRM, and generate cumulative reports.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface SaleItem {
  id: string;
  productName: string;
  quantity: number;
  price: number;
}

export interface DailyReport {
  date: string; // ISO format YYYY-MM-DD
  items: SaleItem[];
  totalValue: number;
  totalQty: number;
  billImage?: string; // Base64
}

export interface UserProfile {
  name: string;
  employeeId: string;
  phoneNumber: string;
  email?: string;
  storeName: string;
  monthlyTarget: number;
  avatar?: string; // Base64
}

export interface Complaint {
  id: string;
  customerName: string;
  phoneNumber: string;
  productModel: string;
  issueType: 'Installation' | 'Complaint';
  isResolved: boolean;
  date: string;
}

export type Tab = 'dashboard' | 'entry' | 'crm' | 'settings';

import { DailyReport, UserProfile, Complaint, SaleItem } from '../types';

const KEYS = {
  USER: 'app_user_profile',
  SALES: 'app_sales_data',
  CRM: 'app_crm_data',
  THEME: 'app_theme_mode',
};

// --- Helpers ---
const getJSON = <T>(key: string): T | null => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : null;
  } catch (e) {
    console.error(`Error reading ${key}`, e);
    return null;
  }
};

const setJSON = (key: string, value: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    console.error(`Error saving ${key}`, e);
    alert('Storage full! Please clear some data or old images.');
  }
};

// --- User ---
export const getUser = (): UserProfile | null => getJSON<UserProfile>(KEYS.USER);
export const saveUser = (user: UserProfile) => setJSON(KEYS.USER, user);
export const logoutUser = () => {
    localStorage.removeItem(KEYS.USER);
    // Optional: Clear data on logout? Usually keep data, just remove auth.
};

// --- Sales ---
export const getSales = (): DailyReport[] => getJSON<DailyReport[]>(KEYS.SALES) || [];

export const saveSaleEntry = (date: string, newItems: SaleItem[], billImage?: string) => {
  const sales = getSales();
  const existingIndex = sales.findIndex((s) => s.date === date);

  const calculateTotals = (items: SaleItem[]) => ({
    totalQty: items.reduce((acc, item) => acc + item.quantity, 0),
    totalValue: items.reduce((acc, item) => acc + (item.price * item.quantity), 0),
  });

  if (existingIndex > -1) {
    // Cumulative Logic: Append items
    const existing = sales[existingIndex];
    const updatedItems = [...existing.items, ...newItems];
    const { totalQty, totalValue } = calculateTotals(updatedItems);

    sales[existingIndex] = {
      ...existing,
      items: updatedItems,
      totalQty,
      totalValue,
      // Update bill image only if a new one is provided, else keep old
      billImage: billImage || existing.billImage,
    };
  } else {
    // New Entry
    const { totalQty, totalValue } = calculateTotals(newItems);
    sales.push({
      date,
      items: newItems,
      totalQty,
      totalValue,
      billImage,
    });
  }
  setJSON(KEYS.SALES, sales);
};

export const updateDailyReport = (date: string, updatedReport: DailyReport) => {
    const sales = getSales();
    const index = sales.findIndex(s => s.date === date);
    if (index > -1) {
        sales[index] = updatedReport;
        setJSON(KEYS.SALES, sales);
    }
};

export const deleteDailyReport = (date: string) => {
    const sales = getSales();
    const filtered = sales.filter(s => s.date !== date);
    setJSON(KEYS.SALES, filtered);
};

// --- CRM ---
export const getComplaints = (): Complaint[] => getJSON<Complaint[]>(KEYS.CRM) || [];
export const saveComplaint = (complaint: Complaint) => {
  const list = getComplaints();
  list.unshift(complaint); // Add to top
  setJSON(KEYS.CRM, list);
};
export const updateComplaint = (updated: Complaint) => {
    const list = getComplaints();
    const index = list.findIndex(c => c.id === updated.id);
    if (index > -1) {
        list[index] = updated;
        setJSON(KEYS.CRM, list);
    }
}

// --- Theme ---
export const getTheme = (): 'light' | 'dark' => (localStorage.getItem(KEYS.THEME) as 'light' | 'dark') || 'light';
export const saveTheme = (theme: 'light' | 'dark') => localStorage.setItem(KEYS.THEME, theme);

// --- Utils ---
export const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                // Max width 1024 to save space
                const scale = 1024 / img.width;
                const width = scale < 1 ? 1024 : img.width;
                const height = scale < 1 ? img.height * scale : img.height;

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                // JPEG quality 0.7
                resolve(canvas.toDataURL('image/jpeg', 0.7));
            };
        };
        reader.onerror = error => reject(error);
    });
};

import { DailyReport, UserProfile } from "../types";
import { getSales } from "./storageService";

export const generateTextReport = (user: UserProfile, report: DailyReport) => {
  const allSales = getSales();

  // Calculate MTD
  const currentMonth = new Date(report.date).getMonth();
  const currentYear = new Date(report.date).getFullYear();

  const mtdValue = allSales
    .filter(s => {
      const d = new Date(s.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear && d <= new Date(report.date);
    })
    .reduce((sum, s) => sum + s.totalValue, 0);

  const dateStr = new Date(report.date).toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: '2-digit' });

  let text = `Name: ${user.name}\n`;
  text += `Date: ${dateStr}\n`;
  text += `Store Location: ${user.storeName}\n\n`;
  text += `Today's Sale Value: = ₹${report.totalValue.toLocaleString()}\n`;
  text += `Today's Sale qty = ${report.totalQty}\n\n`;

  // Aggregate items by name to avoid duplicates in list if entered separately
  const aggregatedItems: Record<string, number> = {};
  report.items.forEach(item => {
      aggregatedItems[item.productName] = (aggregatedItems[item.productName] || 0) + item.quantity;
  });

  Object.entries(aggregatedItems).forEach(([name, qty]) => {
    text += `${name} Qty: = ${qty}\n`;
  });

  text += `\nMTD Sale Value = ₹${mtdValue.toLocaleString()}`;
  return text;
};

export const downloadCSV = (sales: DailyReport[]) => {
    const headers = ['Date', 'Product', 'Quantity', 'Unit Price', 'Total Value'];
    const rows: string[] = [];

    sales.forEach(report => {
        report.items.forEach(item => {
            rows.push([
                report.date,
                `"${item.productName}"`, // Escape quotes
                item.quantity.toString(),
                item.price.toString(),
                (item.quantity * item.price).toString()
            ].join(','));
        });
    });

    const csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" + rows.join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "sales_report.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

import React from 'react';

export const GlassCard = ({ children, className = '', onClick }: { children: React.ReactNode; className?: string, onClick?: () => void }) => (
  <div 
    onClick={onClick}
    className={`bg-white/40 dark:bg-black/40 backdrop-blur-md border border-white/30 dark:border-white/10 rounded-2xl shadow-lg ${className}`}
  >
    {children}
  </div>
);

export const GlassInput = ({ className = '', ...props }: React.InputHTMLAttributes<HTMLInputElement>) => (
  <input
    className={`w-full bg-white/20 dark:bg-black/20 backdrop-blur-sm border border-white/30 dark:border-white/10 rounded-xl px-4 py-3 text-slate-800 dark:text-white placeholder-slate-500 dark:placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-400/50 transition-all ${className}`}
    {...props}
  />
);

export const GlassButton = ({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'danger' }) => {
  const variants = {
    primary: 'bg-blue-600/80 hover:bg-blue-600 text-white shadow-blue-500/30',
    secondary: 'bg-white/30 dark:bg-white/10 hover:bg-white/40 text-slate-800 dark:text-white',
    danger: 'bg-red-500/80 hover:bg-red-600 text-white shadow-red-500/30'
  };

  return (
    <button
      className={`relative overflow-hidden backdrop-blur-md px-6 py-3 rounded-xl font-semibold shadow-lg active:scale-95 transition-all duration-200 flex items-center justify-center gap-2 ${variants[variant]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export const Modal = ({ isOpen, onClose, children, title }: { isOpen: boolean; onClose: () => void; children: React.ReactNode; title: string }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative w-full max-w-md bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl border border-white/20 rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        <div className="p-5 border-b border-white/10 flex justify-between items-center bg-white/10">
          <h3 className="text-xl font-bold text-slate-800 dark:text-white">{title}</h3>
          <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-full transition-colors">
            ✕
          </button>
        </div>
        <div className="p-6 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Home, PlusCircle, Users, Settings, Sun, Moon } from 'lucide-react';
import { Tab, UserProfile } from '../types';
import { GlassCard } from './ui/GlassComponents';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: Tab;
  onTabChange: (tab: Tab) => void;
  isDark: boolean;
  toggleTheme: () => void;
  user: UserProfile | null;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, isDark, toggleTheme, user }) => {
  if (!user) return <>{children}</>;

  const navItems: { id: Tab; icon: React.ElementType; label: string }[] = [
    { id: 'dashboard', icon: Home, label: 'Home' },
    { id: 'entry', icon: PlusCircle, label: 'Entry' },
    { id: 'crm', icon: Users, label: 'CRM' },
    { id: 'settings', icon: Settings, label: 'Settings' },
  ];

  return (
    <div className="flex flex-col min-h-screen relative overflow-hidden font-sans">
      {/* Background Decor Items */}
      <div className="fixed top-[-10%] left-[-10%] w-[500px] h-[500px] bg-blue-400/20 dark:bg-blue-600/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="fixed bottom-[-10%] right-[-10%] w-[400px] h-[400px] bg-purple-400/20 dark:bg-purple-600/10 rounded-full blur-[100px] pointer-events-none" />

      {/* Header */}
      <header className="fixed top-0 left-0 right-0 z-40 px-6 py-4 flex justify-between items-center bg-white/10 backdrop-blur-md border-b border-white/20">
        <div className="flex items-center gap-3">
          {user.avatar ? (
            <img src={user.avatar} alt="Profile" className="w-10 h-10 rounded-full object-cover border-2 border-white/50" />
          ) : (
             <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-blue-400 to-purple-500 flex items-center justify-center text-white font-bold text-lg">
                {user.name.charAt(0)}
             </div>
          )}
          <div>
            <h1 className="text-sm font-medium text-slate-500 dark:text-slate-400">Welcome back,</h1>
            <p className="text-lg font-bold leading-tight">{user.name.split(' ')[0]}</p>
          </div>
        </div>
        <button 
          onClick={toggleTheme} 
          className="p-3 rounded-full bg-white/20 hover:bg-white/30 transition-colors backdrop-blur-sm text-slate-700 dark:text-slate-200"
        >
          {isDark ? <Sun size={20} /> : <Moon size={20} />}
        </button>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-4 pt-24 pb-28 w-full max-w-3xl mx-auto z-10">
        {children}
      </main>

      {/* Bottom Nav */}
      <div className="fixed bottom-0 left-0 right-0 z-40 p-4 pb-6">
        <GlassCard className="max-w-md mx-auto !rounded-full !bg-white/60 dark:!bg-black/60 shadow-2xl border-white/40">
