            {navItems.map((item) => {
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => onTabChange(item.id)}
                  className={`relative flex flex-col items-center gap-1 p-2 transition-all duration-300 ${
                    isActive ? 'text-blue-600 dark:text-blue-400 scale-110' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'
                  }`}
                >
                  <item.icon size={24} strokeWidth={isActive ? 2.5 : 2} />
                  <span className={`text-[10px] font-medium transition-opacity ${isActive ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>
                    {item.label}
                  </span>
                  {isActive && (
                    <span className="absolute -bottom-1 w-1 h-1 bg-current rounded-full" />
                  )}
                </button>
              );
            })}
          </nav>
        </GlassCard>
      </div>
    </div>
  );
};

export default Layout;

import React, { useState, useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import { Calendar, List, Trash2, Maximize2, X, Download, Share2 } from 'lucide-react';
import { DailyReport, SaleItem, UserProfile } from '../types';
import { GlassCard, GlassButton, Modal } from './ui/GlassComponents';
import { generateTextReport } from '../services/reportService';
import { deleteDailyReport, updateDailyReport } from '../services/storageService';

interface DashboardProps {
  sales: DailyReport[];
  user: UserProfile;
  onDataChange: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ sales, user, onDataChange }) => {
  const [viewMode, setViewMode] = useState<'calendar' | 'list'>('calendar');
  const [selectedDateReport, setSelectedDateReport] = useState<DailyReport | null>(null);
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);

  // MTD Calculation
  const { mtdValue, mtdPercentage } = useMemo(() => {
    const now = new Date();
    const currentMonthSales = sales.filter(s => {
      const d = new Date(s.date);
      return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    });
    const value = currentMonthSales.reduce((sum, s) => sum + s.totalValue, 0);
    const percentage = user.monthlyTarget > 0 ? Math.min((value / user.monthlyTarget) * 100, 100) : 0;
    return { mtdValue: value, mtdPercentage: percentage };
  }, [sales, user.monthlyTarget]);

  // Calendar Logic
  const calendarDays = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay(); // 0 is Sunday

    const days = [];
    // Padding
    for (let i = 0; i < firstDay; i++) days.push(null);
    // Days
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      days.push({ day: i, dateStr });
    }
    return days;
  }, []);

  const handleDeleteEntry = (date: string) => {
    if (window.confirm('Are you sure you want to delete this report? This cannot be undone.')) {
      deleteDailyReport(date);
      setSelectedDateReport(null);
      onDataChange();
    }
  };

  const handleRemoveItem = (report: DailyReport, index: number) => {
      const updatedItems = [...report.items];
      updatedItems.splice(index, 1);

      if (updatedItems.length === 0) {
          handleDeleteEntry(report.date);
          return;
      }

      const totalQty = updatedItems.reduce((acc, item) => acc + item.quantity, 0);
      const totalValue = updatedItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);

      const updatedReport = { ...report, items: updatedItems, totalQty, totalValue };
      updateDailyReport(report.date, updatedReport);
      setSelectedDateReport(updatedReport); // Update modal view
      onDataChange();
  };

  const copyReport = (report: DailyReport) => {
    const text = generateTextReport(user, report);
    navigator.clipboard.writeText(text);
    alert('Report copied to clipboard!');
  };

  const downloadImage = (base64: string) => {
      const a = document.createElement("a");
      a.href = base64;
      a.download = `Bill_${Date.now()}.jpg`;
      a.click();
  };

  return (
    <div className="space-y-6">
      {/* Target Section */}
      <GlassCard className="p-6">
        <div className="flex justify-between items-start mb-4">
          <div>
            <h2 className="text-sm font-medium text-slate-500 dark:text-slate-400">Monthly Target</h2>
            <p className="text-2xl font-bold">₹{user.monthlyTarget.toLocaleString()}</p>
          </div>
          <div className="text-right">
            <h2 className="text-sm font-medium text-slate-500 dark:text-slate-400">Achieved (MTD)</h2>
            <p className="text-2xl font-bold text-green-500">₹{mtdValue.toLocaleString()}</p>
          </div>
        </div>

        <div className="h-3 w-full bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-blue-400 to-purple-500 transition-all duration-1000 ease-out"
            style={{ width: `${mtdPercentage}%` }}
          />
        </div>
        <p className="text-xs text-right mt-1 text-slate-500">{mtdPercentage.toFixed(1)}% Completed</p>
      </GlassCard>

      {/* View Toggle */}
      <div className="flex p-1 bg-white/20 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto">
        <button 
          onClick={() => setViewMode('calendar')}
          className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'calendar' ? 'bg-white shadow text-blue-600' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
        >
          Calendar
        </button>
        <button 
          onClick={() => setViewMode('list')}
          className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'list' ? 'bg-white shadow text-blue-600' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
        >
          List View
        </button>
      </div>

      {/* Content Area */}
      {viewMode === 'calendar' ? (
        <GlassCard className="p-4">
          <h3 className="text-center font-bold mb-4 text-lg">
             {new Date().toLocaleString('default', { month: 'long', year: 'numeric' })}
          </h3>
          <div className="grid grid-cols-7 gap-2 mb-2">
            {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
              <div key={d} className="text-center text-xs font-bold text-slate-400">{d}</div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-2">
            {calendarDays.map((d, i) => {
              if (!d) return <div key={i} />;

              const report = sales.find(s => s.date === d.dateStr);
              const isToday = d.dateStr === new Date().toISOString().split('T')[0];

              return (
                <div 
                  key={d.dateStr}
                  onClick={() => report ? setSelectedDateReport(report) : null}
                  className={`
                    aspect-square rounded-xl flex flex-col items-center justify-center cursor-pointer transition-all border
                    ${isToday ? 'border-blue-400 bg-blue-50/50 dark:bg-blue-900/20' : 'border-transparent hover:bg-white/20'}
                    ${report ? 'bg-green-100/30 dark:bg-green-900/20' : ''}
                  `}
                >
                  <span className={`text-xs ${isToday ? 'font-bold text-blue-600' : ''}`}>{d.day}</span>
                  {report ? (
                    <span className="text-[10px] font-bold text-green-600 dark:text-green-400 mt-1">
                      {report.totalQty}u
                    </span>
                  ) : (
                    <span className="text-[9px] text-slate-300 dark:text-slate-600 mt-1">-</span>
                  )}
                </div>
              );
            })}
          </div>
        </GlassCard>
      ) : (
        <div className="space-y-4">
          {[...sales].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(report => (
             <GlassCard key={report.date} className="p-4" onClick={() => setSelectedDateReport(report)}>
                <div className="flex justify-between items-center">
                    <div>
                        <p className="font-bold">{new Date(report.date).toLocaleDateString()}</p>
                        <p className="text-sm text-slate-500">{report.totalQty} items • ₹{report.totalValue.toLocaleString()}</p>
                    </div>
                    <div className="h-8 w-8 bg-blue-100 dark:bg-blue-900 rounded-full flex items-center justify-center text-blue-600">
                        <List size={16} />
                    </div>
                </div>
             </GlassCard>
          ))}
          {sales.length === 0 && <p className="text-center text-slate-500 mt-8">No records found.</p>}
        </div>
      )}

      {/* Details Modal */}
      <Modal 
        isOpen={!!selectedDateReport} 
        onClose={() => setSelectedDateReport(null)}
        title={selectedDateReport ? new Date(selectedDateReport.date).toDateString() : ''}
      >
        {selectedDateReport && (
          <div className="space-y-4">
             {/* Stats */}
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-blue-50 dark:bg-blue-900/30 p-3 rounded-lg text-center">
                    <p className="text-xs text-slate-500">Value</p>
                    <p className="font-bold text-blue-600">₹{selectedDateReport.totalValue.toLocaleString()}</p>
                </div>
                <div className="bg-purple-50 dark:bg-purple-900/30 p-3 rounded-lg text-center">
                    <p className="text-xs text-slate-500">Quantity</p>
                    <p className="font-bold text-purple-600">{selectedDateReport.totalQty}</p>
                </div>
             </div>

             {/* Items List */}
             <div className="space-y-2">
                <h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Items Sold</h4>
                {selectedDateReport.items.map((item, idx) => (
                    <div key={idx} className="flex justify-between items-center p-2 bg-white/40 dark:bg-white/5 rounded-lg border border-white/10">
                        <div>
                            <p className="font-medium">{item.productName}</p>
                            <p className="text-xs text-slate-500">₹{item.price} x {item.quantity}</p>
                        </div>
                        <div className="flex items-center gap-3">
                            <p className="font-bold">₹{item.price * item.quantity}</p>
                            <button onClick={() => handleRemoveItem(selectedDateReport, idx)} className="text-red-400 hover:text-red-600 p-1">
                                <Trash2 size={14} />
                            </button>
                        </div>
                    </div>
                ))}
             </div>

             {/* Bill Image */}
             {selectedDateReport.billImage && (
                 <div className="mt-4">
                     <h4 className="text-sm font-semibold text-slate-500 mb-2">Bill Copy</h4>
                     <div className="relative group rounded-xl overflow-hidden border border-white/20">
                         <img 
                            src={selectedDateReport.billImage} 
                            alt="Bill" 
                            className="w-full h-32 object-cover object-top"
                         />
                         <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2">
                             <button onClick={() => setZoomedImage(selectedDateReport.billImage!)} className="p-2 bg-white rounded-full text-black">
                                 <Maximize2 size={16} />
                             </button>
                             <button onClick={() => downloadImage(selectedDateReport.billImage!)} className="p-2 bg-white rounded-full text-black">
                                 <Download size={16} />
                             </button>
                         </div>
                     </div>
                 </div>
             )}

             {/* Actions */}
             <div className="grid grid-cols-2 gap-3 mt-6">
                <GlassButton onClick={() => copyReport(selectedDateReport)}>
                    Copy Report
                </GlassButton>
                <GlassButton variant="danger" onClick={() => handleDeleteEntry(selectedDateReport.date)}>
                    Delete All
                </GlassButton>
             </div>
          </div>
        )}
      </Modal>

      {/* Image Zoom Modal */}
      {zoomedImage && (
          <div className="fixed inset-0 z-[60] bg-black/90 backdrop-blur-xl flex items-center justify-center p-4">
              <button 
                onClick={() => setZoomedImage(null)}
                className="absolute top-4 right-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20"
              >
                  <X size={24} />
              </button>
              <img 
                src={zoomedImage} 
                className="max-w-full max-h-full object-contain shadow-2xl rounded-lg"
                alt="Zoomed Bill"
              />
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Camera, Plus, Trash2, Send, Copy } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton, Modal } from './ui/GlassComponents';
import { SaleItem, UserProfile } from '../types';
import { saveSaleEntry, compressImage } from '../services/storageService';
import { generateTextReport } from '../services/reportService';
import { getSales } from '../services/storageService';

interface NewEntryProps {
  user: UserProfile;
  onEntryComplete: () => void;
}

const NewEntry: React.FC<NewEntryProps> = ({ user, onEntryComplete }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [items, setItems] = useState<SaleItem[]>([
    { id: '1', productName: '', quantity: 1, price: 0 }
  ]);
  const [billImage, setBillImage] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const addItem = () => {
    setItems([...items, { id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
  };

  const removeItem = (index: number) => {
    if (items.length === 1) return;
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);
  };

  const updateItem = (index: number, field: keyof SaleItem, value: string | number) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    setItems(newItems);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const compressed = await compressImage(e.target.files[0]);
        setBillImage(compressed);
      } catch (err) {
        alert('Error uploading image');
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!billImage && !confirm("Save without bill image?")) return;

    setIsSubmitting(true);

    // Simulate slight delay for UX
    setTimeout(() => {
        saveSaleEntry(date, items, billImage || undefined);
        setIsSubmitting(false);
        setShowSuccessModal(true);
    }, 500);
  };

  const handleShareWhatsApp = () => {
      // Get the *updated* report for this date to ensure cumulative data is shared
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
      }
  };

  const handleCopyText = () => {
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          navigator.clipboard.writeText(text);
          alert('Report copied!');
      }
  };

  const resetForm = () => {
      setItems([{ id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
      setBillImage(null);
      setDate(new Date().toISOString().split('T')[0]);
      setShowSuccessModal(false);
      onEntryComplete();
  };

  const totalValue = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <>
    <div className="space-y-6 animate-in slide-in-from-bottom-5 fade-in duration-500">
      <div className="text-center mb-6">
        <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">New Sales Entry</h2>
        <p className="text-slate-500 text-sm">Log your daily performance</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <GlassCard className="p-4 space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Date</label>
            <GlassInput 
                type="date" 
                value={date} 
                onChange={e => setDate(e.target.value)}
                required
            />
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300">Products</label>
                <button type="button" onClick={addItem} className="text-blue-500 text-sm font-bold flex items-center gap-1">
                    <Plus size={16} /> Add Another
                </button>
            </div>

            {items.map((item, index) => (
              <div key={item.id} className="p-3 bg-white/30 dark:bg-black/20 rounded-xl space-y-3 relative group">
                {items.length > 1 && (
                    <button 
                        type="button" 
                        onClick={() => removeItem(index)}
                        className="absolute -top-2 -right-2 p-1 bg-red-100 text-red-500 rounded-full shadow-sm hover:bg-red-200"
                    >
                        <Trash2 size={14} />
                    </button>
                )}

                <div>
                    <input 
                        placeholder="Product Name (e.g. Iron)"
                        className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none text-slate-800 dark:text-white placeholder-slate-400"
                        value={item.productName}
                        onChange={e => updateItem(index, 'productName', e.target.value)}
                        required
                    />
                </div>
                <div className="flex gap-4">
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Qty</label>
                        <input 
                            type="number"
                            min="1"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.quantity}
                            onChange={e => updateItem(index, 'quantity', parseInt(e.target.value) || 0)}
                            required
                        />
                    </div>
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Price (₹)</label>
                        <input 
                            type="number"
                            min="0"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.price}
                            onChange={e => updateItem(index, 'price', parseFloat(e.target.value) || 0)}
                            required
                        />
                    </div>
                </div>
              </div>
            ))}
          </div>
        </GlassCard>

        <GlassCard className="p-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className={`w-16 h-16 rounded-xl flex items-center justify-center border-2 border-dashed ${billImage ? 'border-green-400 bg-green-50' : 'border-slate-300 bg-slate-50 dark:bg-slate-800 dark:border-slate-600'}`}>
                    {billImage ? (
                        <img src={billImage} className="w-full h-full object-cover rounded-lg" alt="Bill" />
                    ) : (
                        <Camera className="text-slate-400" />
                    )}
                </div>
                <div>
                    <p className="font-medium">Bill Image</p>
                    <p className="text-xs text-slate-500">{billImage ? 'Image added' : 'Tap to upload'}</p>
                </div>
            </div>
            <label className="relative">
                <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
                <span className="px-4 py-2 bg-slate-200 dark:bg-slate-700 rounded-lg text-sm font-semibold cursor-pointer">
                    {billImage ? 'Change' : 'Upload'}
                </span>
            </label>
        </GlassCard>

        <GlassCard className="p-4 bg-blue-600/10 border-blue-200 dark:border-blue-900">
            <div className="flex justify-between items-center">
                <span className="text-slate-600 dark:text-slate-300">Total Value</span>
                <span className="text-2xl font-bold text-blue-600 dark:text-blue-400">₹{totalValue.toLocaleString()}</span>
            </div>
        </GlassCard>

        <GlassButton type="submit" className="w-full" disabled={isSubmitting}>
            {isSubmitting ? 'Saving...' : 'Save Entry'}
        </GlassButton>
      </form>
    </div>

    {/* Success Modal */}
    <Modal 
        isOpen={showSuccessModal} 
        onClose={resetForm} 
        title="Entry Saved!"
    >
        <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto text-green-600">
                <Copy size={32} />
            </div>
            <p className="text-slate-600 dark:text-slate-300">
                Your data has been added to the cumulative report for <b>{date}</b>.
            </p>

            <div className="grid grid-cols-2 gap-4">
                <button 
                    onClick={handleShareWhatsApp}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20 transition-colors border border-[#25D366]/20"
                >
                    <Send size={24} />
                    <span className="font-bold text-sm">WhatsApp</span>
                </button>
                <button 
                    onClick={handleCopyText}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 transition-colors border border-blue-500/20"
                >
                    <Copy size={24} />
                    <span className="font-bold text-sm">Copy</span>
                </button>
            </div>

            <GlassButton onClick={resetForm} variant="secondary" className="w-full">
                Close & New Entry
            </GlassButton>
        </div>
    </Modal>
    </>
  );
};

export default NewEntry;

import React, { useState } from 'react';
import { User, Phone, Tool, CheckCircle, XCircle } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton } from './ui/GlassComponents';
import { Complaint } from '../types';
import { getComplaints, saveComplaint, updateComplaint } from '../services/storageService';

const CRM: React.FC = () => {
  const [complaints, setComplaints] = useState<Complaint[]>(getComplaints());
  const [formData, setFormData] = useState({
    customerName: '',
    phoneNumber: '',
    productModel: '',
    issueType: 'Installation' as const
  });
  const [view, setView] = useState<'new' | 'history'>('history');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newComplaint: Complaint = {
      id: Date.now().toString(),
      ...formData,
      isResolved: false,
      date: new Date().toISOString()
    };
    saveComplaint(newComplaint);
    setComplaints(getComplaints());
    setFormData({ customerName: '', phoneNumber: '', productModel: '', issueType: 'Installation' });
    setView('history');
  };

  const toggleStatus = (complaint: Complaint) => {
    const updated = { ...complaint, isResolved: !complaint.isResolved };
    updateComplaint(updated);
    setComplaints(getComplaints());
  };

  return (
    <div className="space-y-6">
       <div className="flex justify-between items-center mb-6">
           <h2 className="text-2xl font-bold">CRM</h2>
           <button 
             onClick={() => setView(view === 'new' ? 'history' : 'new')}
             className="text-blue-500 font-semibold"
           >
               {view === 'new' ? 'Cancel' : '+ New Ticket'}
           </button>
       </div>

       {view === 'new' ? (
           <form onSubmit={handleSubmit} className="space-y-4 animate-in fade-in slide-in-from-right-4">
               <GlassCard className="p-6 space-y-4">
                   <h3 className="font-semibold text-lg border-b border-white/10 pb-2">New Ticket</h3>
                   <div className="space-y-2">
                       <label className="text-xs font-bold uppercase text-slate-400">Customer Name</label>
                       <GlassInput 
                           required
                           placeholder="John Doe"
                           value={formData.customerName} 
                           onChange={e => setFormData({...formData, customerName: e.target.value})} 
                       />
                   </div>
                   <div className="space-y-2">
                       <label className="text-xs font-bold uppercase text-slate-400">Phone</label>
                       <GlassInput 
                           required
                           type="tel"
                           placeholder="9876543210"
                           value={formData.phoneNumber} 
                           onChange={e => setFormData({...formData, phoneNumber: e.target.value})} 
                       />
                   </div>
                   <div className="space-y-2">
                       <label className="text-xs font-bold uppercase text-slate-400">Product Model</label>
                       <GlassInput 
                           required
                           placeholder="Mixer Grinder GX1"
                           value={formData.productModel} 
                           onChange={e => setFormData({...formData, productModel: e.target.value})} 
                       />
                   </div>
                   <div className="space-y-2">
                       <label className="text-xs font-bold uppercase text-slate-400">Type</label>
                       <select 
                           className="w-full bg-white/20 dark:bg-black/20 backdrop-blur-sm border border-white/30 rounded-xl px-4 py-3 outline-none"
                           value={formData.issueType}
                           onChange={e => setFormData({...formData, issueType: e.target.value as any})}
                       >
                           <option value="Installation" className="text-black">Installation</option>
                           <option value="Complaint" className="text-black">Complaint</option>
                       </select>
                   </div>
                   <GlassButton type="submit" className="w-full mt-4">Create Ticket</GlassButton>
               </GlassCard>
           </form>
       ) : (
           <div className="space-y-4">
               {complaints.length === 0 && <p className="text-center text-slate-500 py-10">No tickets raised yet.</p>}
               {complaints.map(c => (
                   <GlassCard key={c.id} className="p-4 relative overflow-hidden group">
                       <div className={`absolute top-0 left-0 w-1 h-full ${c.isResolved ? 'bg-green-500' : 'bg-red-500'}`} />
                       <div className="pl-3 flex justify-between items-start">
                           <div>
                               <div className="flex items-center gap-2 mb-1">
                                   <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wider ${c.issueType === 'Installation' ? 'bg-blue-100 text-blue-600' : 'bg-orange-100 text-orange-600'}`}>
                                       {c.issueType}
                                   </span>
                                   <span className="text-xs text-slate-400">{new Date(c.date).toLocaleDateString()}</span>
                               </div>
                               <h4 className="font-bold text-lg">{c.customerName}</h4>
                               <p className="text-sm text-slate-500">{c.productModel}</p>
                               <a href={`tel:${c.phoneNumber}`} className="text-sm text-blue-500 flex items-center gap-1 mt-1">
                                   <Phone size={12} /> {c.phoneNumber}
                               </a>
                           </div>
                           <button 
                               onClick={() => toggleStatus(c)}
                               className={`p-2 rounded-full transition-colors ${c.isResolved ? 'text-green-500 bg-green-50' : 'text-slate-300 bg-slate-100 dark:bg-slate-800'}`}
                           >
                               {c.isResolved ? <CheckCircle /> : <div className="w-6 h-6 rounded-full border-2 border-slate-300" />}
                           </button>
                       </div>
                   </GlassCard>
               ))}
           </div>
       )}
    </div>
  );
};

export default CRM;

import React, { useState } from 'react';
import { User, LogOut, FileText, Download, ExternalLink } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton } from './ui/GlassComponents';
import { UserProfile } from '../types';
import { saveUser, logoutUser, getSales, compressImage } from '../services/storageService';
import { downloadCSV } from '../services/reportService';

interface SettingsProps {
  user: UserProfile;
  onUpdateUser: (u: UserProfile) => void;
  onLogout: () => void;
}

const Settings: React.FC<SettingsProps> = ({ user, onUpdateUser, onLogout }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(user);

  const handleSave = () => {
    saveUser(editForm);
    onUpdateUser(editForm);
    setIsEditing(false);
  };

  const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          try {
              const base64 = await compressImage(e.target.files[0]);
              setEditForm(prev => ({ ...prev, avatar: base64 }));
          } catch (err) {
              alert('Image too large');
          }
      }
  };

  const exportJSON = () => {
    const data = JSON.stringify({ user, sales: getSales() }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handlePrintView = () => {
      // Create a print-friendly window
      const sales = getSales();
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(`
            <html>
                <head>
                    <title>Print Report</title>
                    <style>
                        body { font-family: sans-serif; padding: 20px; }
                        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f2f2f2; }
                        .header { margin-bottom: 20px; }
                        img { max-width: 100px; }
                    </style>
                </head>
                <body>
                    <div class="header">
                        <h1>Sales Report</h1>
                        <p><strong>Executive:</strong> ${user.name} (${user.employeeId})</p>
                        <p><strong>Store:</strong> ${user.storeName}</p>
                        <p><strong>Generated:</strong> ${new Date().toLocaleDateString()}</p>
                    </div>
                    <table>
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th>Products</th>
                                <th>Total Qty</th>
                                <th>Total Value</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${sales.map(s => `
                                <tr>
                                    <td>${s.date}</td>
                                    <td>
                                        ${s.items.map(i => `<div>${i.productName} (${i.quantity} x ${i.price})</div>`).join('')}
                                    </td>
                                    <td>${s.totalQty}</td>
                                    <td>₹${s.totalValue}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                    <script>window.print();</script>
                </body>
            </html>
        `);
        printWindow.document.close();
      }
  };

  return (
    <div className="space-y-6">
        {/* Profile Card */}
        <GlassCard className="p-6 text-center relative">
            <div className="relative inline-block">
                <div className="w-24 h-24 rounded-full overflow-hidden mx-auto border-4 border-white/50 shadow-xl mb-4">
                    {editForm.avatar ? (
                        <img src={editForm.avatar} className="w-full h-full object-cover" />
                    ) : (
                        <div className="w-full h-full bg-slate-200 flex items-center justify-center text-3xl font-bold text-slate-400">
                            {user.name.charAt(0)}
                        </div>
                    )}
                </div>
                {isEditing && (
                    <label className="absolute bottom-4 right-0 bg-blue-500 text-white p-1 rounded-full cursor-pointer shadow-lg">
                        <User size={16} />
                        <input type="file" className="hidden" accept="image/*" onChange={handleAvatarChange} />
                    </label>
                )}
            </div>

            {isEditing ? (
                <div className="space-y-3 text-left">
                    <GlassInput value={editForm.name} onChange={e => setEditForm({...editForm, name: e.target.value})} placeholder="Name" />
                    <GlassInput value={editForm.storeName} onChange={e => setEditForm({...editForm, storeName: e.target.value})} placeholder="Store" />
                    <GlassInput value={editForm.employeeId} onChange={e => setEditForm({...editForm, employeeId: e.target.value})} placeholder="Emp ID" />
                    <div className="flex gap-2 items-center">
                        <label className="whitespace-nowrap text-sm text-slate-500 w-24">Target (₹)</label>
                        <GlassInput type="number" value={editForm.monthlyTarget} onChange={e => setEditForm({...editForm, monthlyTarget: parseInt(e.target.value) || 0})} />
                    </div>
                    <div className="flex gap-2 pt-2">
                        <GlassButton onClick={handleSave} className="flex-1">Save</GlassButton>
                        <GlassButton onClick={() => { setIsEditing(false); setEditForm(user); }} variant="secondary" className="flex-1">Cancel</GlassButton>
                    </div>
                </div>
            ) : (
                <>
                    <h2 className="text-xl font-bold">{user.name}</h2>
                    <p className="text-slate-500">{user.storeName}</p>
                    <p className="text-xs text-slate-400 mt-1">ID: {user.employeeId}</p>
                    <button onClick={() => setIsEditing(true)} className="text-blue-500 text-sm mt-4 font-medium hover:underline">Edit Profile</button>
                </>
            )}
        </GlassCard>

        {/* Data Management */}
        <h3 className="font-bold text-lg px-2">Data & Reports</h3>
        <div className="grid grid-cols-2 gap-4">
            <GlassCard className="p-4 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-white/50 transition-colors" onClick={() => downloadCSV(getSales())}>
                <FileText className="text-green-600" />
                <span className="text-sm font-medium">Export Excel</span>
            </GlassCard>
            <GlassCard className="p-4 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-white/50 transition-colors" onClick={handlePrintView}>
                <Download className="text-red-500" />
                <span className="text-sm font-medium">Print PDF</span>
            </GlassCard>
            <GlassCard className="p-4 flex flex-col items-center justify-center gap-2 cursor-pointer hover:bg-white/50 transition-colors" onClick={exportJSON}>
                <Download className="text-blue-500" />
                <span className="text-sm font-medium">Backup Data</span>
            </GlassCard>
        </div>

        {/* Support */}
        <h3 className="font-bold text-lg px-2 mt-4">Support</h3>
        <GlassCard className="divide-y divide-white/20">
            <a href="https://wa.me/917039920000" target="_blank" rel="noreferrer" className="flex items-center justify-between p-4 hover:bg-white/30 transition-colors">
                <span className="font-medium">WhatsApp Support</span>
                <ExternalLink size={16} className="text-slate-400" />
            </a>
            <a href="https://www.bajajelectricals.com/" target="_blank" rel="noreferrer" className="flex items-center justify-between p-4 hover:bg-white/30 transition-colors">
                <span className="font-medium">Bajaj Website</span>
                <ExternalLink size={16} className="text-slate-400" />
            </a>
        </GlassCard>

        <GlassButton variant="danger" onClick={onLogout} className="w-full flex items-center justify-center gap-2">
            <LogOut size={18} /> Logout
        </GlassButton>

        <p className="text-center text-xs text-slate-400 py-4">Version 1.0.0 • Built for Sales Executives</p>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { GlassCard, GlassInput, GlassButton } from './ui/GlassComponents';
import { UserProfile } from '../types';
import { saveUser } from '../services/storageService';

const Auth = ({ onLogin }: { onLogin: (user: UserProfile) => void }) => {
  const [formData, setFormData] = useState({
    name: '',
    employeeId: '',
    phoneNumber: '',
    storeName: '',
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.employeeId || !formData.storeName) return;

    const user: UserProfile = {
      ...formData,
      monthlyTarget: 100000, // Default target
    };
    saveUser(user);
    onLogin(user);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <GlassCard className="w-full max-w-md p-8 animate-in zoom-in-95 duration-500">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600 mb-2">SalesTrack</h1>
          <p className="text-slate-500">Welcome back, Executive.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Full Name</label>
            <GlassInput required placeholder="John Doe" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
          </div>
          <div>
             <label className="block text-sm font-medium text-slate-600 mb-1">Employee ID</label>
             <GlassInput required placeholder="EMP123" value={formData.employeeId} onChange={e => setFormData({...formData, employeeId: e.target.value})} />
          </div>
          <div>
             <label className="block text-sm font-medium text-slate-600 mb-1">Phone Number</label>
             <GlassInput required type="tel" placeholder="9876543210" value={formData.phoneNumber} onChange={e => setFormData({...formData, phoneNumber: e.target.value})} />
          </div>
          <div>
             <label className="block text-sm font-medium text-slate-600 mb-1">Store Name</label>
             <GlassInput required placeholder="Reliance Digital, JPNagara" value={formData.storeName} onChange={e => setFormData({...formData, storeName: e.target.value})} />
          </div>

          <GlassButton type="submit" className="w-full mt-6">
            Get Started
          </GlassButton>
        </form>
      </GlassCard>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import NewEntry from './components/NewEntry';
import CRM from './components/CRM';
import Settings from './components/Settings';
import { Tab, UserProfile, DailyReport } from './types';
import { getUser, logoutUser, getSales, getTheme, saveTheme } from './services/storageService';

const App = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [salesData, setSalesData] = useState<DailyReport[]>([]);
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    // Initialize Theme
    const savedTheme = getTheme();
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }

    // Load User & Data
    const storedUser = getUser();
    if (storedUser) {
      setUser(storedUser);
      setSalesData(getSales());
    }

    // Fake Splash Screen
    setTimeout(() => setIsLoading(false), 1500);
  }, []);

  const toggleTheme = () => {
    const newMode = !isDark;
    setIsDark(newMode);
    if (newMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    saveTheme(newMode ? 'dark' : 'light');
  };

  const handleLogin = (newUser: UserProfile) => {
    setUser(newUser);
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
  };

  const refreshData = () => {
    setSalesData(getSales());
  };

  if (isLoading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-white dark:bg-black transition-colors">
        <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-blue-500 to-purple-500 animate-pulse mb-4 shadow-2xl shadow-blue-500/50"></div>
        <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">SalesTrack</h1>
      </div>
    );
  }

  if (!user) {
    return <Auth onLogin={handleLogin} />;
  }

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={setActiveTab}
      isDark={isDark}
      toggleTheme={toggleTheme}
      user={user}
    >
      {activeTab === 'dashboard' && <Dashboard sales={salesData} user={user} onDataChange={refreshData} />}
      {activeTab === 'entry' && <NewEntry user={user} onEntryComplete={refreshData} />}
      {activeTab === 'crm' && <CRM />}
      {activeTab === 'settings' && <Settings user={user} onUpdateUser={setUser} onLogout={handleLogout} />}
    </Layout>
  );
};

export default App;

