export type Tab = 'dashboard' | 'entry' | 'crm' | 'settings';

import { DailyReport, UserProfile, Complaint, SaleItem } from '../types';

const KEYS = {
  USER: 'app_user_profile',
  SALES: 'app_sales_data',
  CRM: 'app_crm_data',
  THEME: 'app_theme_mode',
};

// --- Helpers ---
const getJSON = <T>(key: string): T | null => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : null;
  } catch (e) {
    console.error(`Error reading ${key}`, e);
    return null;
  }
};

const setJSON = (key: string, value: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    console.error(`Error saving ${key}`, e);
    alert('Storage full! Please clear some data or old images.');
  }
};

// --- User ---
export const getUser = (): UserProfile | null => getJSON<UserProfile>(KEYS.USER);
export const saveUser = (user: UserProfile) => setJSON(KEYS.USER, user);
export const logoutUser = () => {
    localStorage.removeItem(KEYS.USER);
};

// --- Sales ---
export const getSales = (): DailyReport[] => getJSON<DailyReport[]>(KEYS.SALES) || [];

export const saveSaleEntry = (date: string, newItems: SaleItem[], newBillImages: string[] = []) => {
  const sales = getSales();
  const existingIndex = sales.findIndex((s) => s.date === date);

  const calculateTotals = (items: SaleItem[]) => ({
    totalQty: items.reduce((acc, item) => acc + item.quantity, 0),
    totalValue: items.reduce((acc, item) => acc + (item.price * item.quantity), 0),
  });

  if (existingIndex > -1) {
    // Cumulative Logic: Append items
    const existing = sales[existingIndex];
    const updatedItems = [...existing.items, ...newItems];
    const { totalQty, totalValue } = calculateTotals(updatedItems);

    // Merge images: Handle legacy 'billImage' and new 'billImages'
    const existingImages = existing.billImages || (existing.billImage ? [existing.billImage] : []);
    const mergedImages = [...existingImages, ...newBillImages];

    sales[existingIndex] = {
      ...existing,
      items: updatedItems,
      totalQty,
      totalValue,
      billImages: mergedImages,
      billImage: undefined, // Clear legacy field
    };
  } else {
    // New Entry
    const { totalQty, totalValue } = calculateTotals(newItems);
    sales.push({
      date,
      items: newItems,
      totalQty,
      totalValue,
      billImages: newBillImages,
    });
  }
  setJSON(KEYS.SALES, sales);
};

export const updateDailyReport = (date: string, updatedReport: DailyReport) => {
    const sales = getSales();
    const index = sales.findIndex(s => s.date === date);
    if (index > -1) {
        sales[index] = updatedReport;
        setJSON(KEYS.SALES, sales);
    }
};

export const deleteDailyReport = (date: string) => {
    const sales = getSales();
    const filtered = sales.filter(s => s.date !== date);
    setJSON(KEYS.SALES, filtered);
};

// --- CRM ---
export const getComplaints = (): Complaint[] => getJSON<Complaint[]>(KEYS.CRM) || [];
export const saveComplaint = (complaint: Complaint) => {
  const list = getComplaints();
  list.unshift(complaint); // Add to top
  setJSON(KEYS.CRM, list);
};
export const updateComplaint = (updated: Complaint) => {
    const list = getComplaints();
    const index = list.findIndex(c => c.id === updated.id);
    if (index > -1) {
        list[index] = updated;
        setJSON(KEYS.CRM, list);
    }
}

// --- Theme ---
export const getTheme = (): 'light' | 'dark' => (localStorage.getItem(KEYS.THEME) as 'light' | 'dark') || 'light';
export const saveTheme = (theme: 'light' | 'dark') => localStorage.setItem(KEYS.THEME, theme);

// --- Utils ---
export const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                // Max width 1024 to save space
                const scale = 1024 / img.width;
                const width = scale < 1 ? 1024 : img.width;
                const height = scale < 1 ? img.height * scale : img.height;

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                // JPEG quality 0.7
                resolve(canvas.toDataURL('image/jpeg', 0.7));
            };
        };
        reader.onerror = error => reject(error);
    });
};

import React, { useState } from 'react';
import { Camera, Plus, Trash2, Send, Copy, X } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton, Modal } from './ui/GlassComponents';
import { SaleItem, UserProfile } from '../types';
import { saveSaleEntry, compressImage } from '../services/storageService';
import { generateTextReport } from '../services/reportService';
import { getSales } from '../services/storageService';

interface NewEntryProps {
  user: UserProfile;
  onEntryComplete: () => void;
}

const NewEntry: React.FC<NewEntryProps> = ({ user, onEntryComplete }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [items, setItems] = useState<SaleItem[]>([
    { id: '1', productName: '', quantity: 1, price: 0 }
  ]);
  const [billImages, setBillImages] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const addItem = () => {
    setItems([...items, { id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
  };

  const removeItem = (index: number) => {
    if (items.length === 1) return;
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);
  };

  const updateItem = (index: number, field: keyof SaleItem, value: string | number) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    setItems(newItems);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      try {
        const files = Array.from(e.target.files);
        const newImages = await Promise.all(files.map(f => compressImage(f)));
        setBillImages(prev => [...prev, ...newImages]);
      } catch (err) {
        alert('Error uploading images');
      }
    }
  };

  const removeImage = (index: number) => {
      setBillImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (billImages.length === 0 && !confirm("Save without bill image?")) return;

    setIsSubmitting(true);

    // Simulate slight delay for UX
    setTimeout(() => {
        saveSaleEntry(date, items, billImages);
        setIsSubmitting(false);
        setShowSuccessModal(true);
    }, 500);
  };

  const handleShareWhatsApp = () => {
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
      }
  };

  const handleCopyText = () => {
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          navigator.clipboard.writeText(text);
          alert('Report copied!');
      }
  };

  const resetForm = () => {
      setItems([{ id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
      setBillImages([]);
      setDate(new Date().toISOString().split('T')[0]);
      setShowSuccessModal(false);
      onEntryComplete();
  };

  const totalValue = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <>
    <div className="space-y-6 animate-in slide-in-from-bottom-5 fade-in duration-500">
      <div className="text-center mb-6">
        <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">New Sales Entry</h2>
        <p className="text-slate-500 text-sm">Log your daily performance</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <GlassCard className="p-4 space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Date</label>
            <GlassInput 
                type="date" 
                value={date} 
                onChange={e => setDate(e.target.value)}
                required
            />
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300">Products</label>
                <button type="button" onClick={addItem} className="text-blue-500 text-sm font-bold flex items-center gap-1">
                    <Plus size={16} /> Add Another
                </button>
            </div>

            {items.map((item, index) => (
              <div key={item.id} className="p-3 bg-white/30 dark:bg-black/20 rounded-xl space-y-3 relative group">
                {items.length > 1 && (
                    <button 
                        type="button" 
                        onClick={() => removeItem(index)}
                        className="absolute -top-2 -right-2 p-1 bg-red-100 text-red-500 rounded-full shadow-sm hover:bg-red-200"
                    >
                        <Trash2 size={14} />
                    </button>
                )}

                <div>
                    <input 
                        placeholder="Product Name (e.g. Iron)"
                        className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none text-slate-800 dark:text-white placeholder-slate-400"
                        value={item.productName}
                        onChange={e => updateItem(index, 'productName', e.target.value)}
                        required
                    />
                </div>
                <div className="flex gap-4">
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Qty</label>
                        <input 
                            type="number"
                            min="1"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.quantity}
                            onChange={e => updateItem(index, 'quantity', parseInt(e.target.value) || 0)}
                            required
                        />
                    </div>
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Price (₹)</label>
                        <input 
                            type="number"
                            min="0"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.price}
                            onChange={e => updateItem(index, 'price', parseFloat(e.target.value) || 0)}
                            required
                        />
                    </div>
                </div>
              </div>
            ))}
          </div>
        </GlassCard>

        {/* Bill Images Section */}
        <GlassCard className="p-4">
            <div className="flex justify-between items-center mb-4">
                <div>
                    <p className="font-medium">Bill Copies</p>
                    <p className="text-xs text-slate-500">{billImages.length} images selected</p>
                </div>
                <label className="cursor-pointer bg-slate-200 dark:bg-slate-700 px-3 py-1.5 rounded-lg text-sm font-semibold flex items-center gap-1 hover:bg-slate-300 dark:hover:bg-slate-600 transition-colors">
                    <Plus size={16} /> Add Photo
                    <input type="file" multiple accept="image/*" onChange={handleImageUpload} className="hidden" />
                </label>
            </div>

            {billImages.length === 0 ? (
                <div className="border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-6 text-center">
                    <Camera className="mx-auto text-slate-400 mb-2" size={24} />
                    <p className="text-sm text-slate-400">No bills added yet</p>
                </div>
            ) : (
                <div className="flex gap-2 overflow-x-auto pb-2 snap-x">
                    {billImages.map((img, idx) => (
                        <div key={idx} className="relative flex-shrink-0 w-24 h-24 snap-start">
                            <img src={img} alt={`Bill ${idx}`} className="w-full h-full object-cover rounded-lg border border-white/20" />
                            <button 
                                type="button"
                                onClick={() => removeImage(idx)}
                                className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 shadow-md"
                            >
                                <X size={12} />
                            </button>
                        </div>
                    ))}
                </div>
            )}
        </GlassCard>

        <GlassCard className="p-4 bg-blue-600/10 border-blue-200 dark:border-blue-900">
            <div className="flex justify-between items-center">
                <span className="text-slate-600 dark:text-slate-300">Total Value</span>
                <span className="text-2xl font-bold text-blue-600 dark:text-blue-400">₹{totalValue.toLocaleString()}</span>
            </div>
        </GlassCard>

        <GlassButton type="submit" className="w-full" disabled={isSubmitting}>
            {isSubmitting ? 'Saving...' : 'Save Entry'}
        </GlassButton>
      </form>
    </div>

    {/* Success Modal */}
    <Modal 
        isOpen={showSuccessModal} 
        onClose={resetForm} 
        title="Entry Saved!"
    >
        <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto text-green-600">
                <Copy size={32} />
            </div>
            <p className="text-slate-600 dark:text-slate-300">
                Your data has been added to the cumulative report for <b>{date}</b>.
            </p>

            <div className="grid grid-cols-2 gap-4">
                <button 
                    onClick={handleShareWhatsApp}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20 transition-colors border border-[#25D366]/20"
                >
                    <Send size={24} />
                    <span className="font-bold text-sm">WhatsApp</span>
                </button>
                <button 
                    onClick={handleCopyText}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 transition-colors border border-blue-500/20"
                >
                    <Copy size={24} />
                    <span className="font-bold text-sm">Copy</span>
                </button>
            </div>

            <GlassButton onClick={resetForm} variant="secondary" className="w-full">
                Close & New Entry
            </GlassButton>
        </div>
    </Modal>
    </>
  );
};

export default NewEntry;

import React, { useState, useMemo } from 'react';
