    >
        <div className="text-center space-y-6">
            <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto ${isWeekOff ? 'bg-gray-100 text-gray-500' : 'bg-green-100 text-green-600'}`}>
                {isWeekOff ? <Check size={32} /> : <Copy size={32} />}
            </div>
            <p className="text-slate-600 dark:text-slate-300">
                {isWeekOff 
                    ? `Marked ${date} as Week Off.` 
                    : `Your data has been added to the cumulative report for ${date}.`
                }
            </p>

            {!isWeekOff && (
            <div className="grid grid-cols-2 gap-4">
                <button 
                    onClick={handleShareWhatsApp}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20 transition-colors border border-[#25D366]/20"
