      <form onSubmit={handleSubmit} className="space-y-6">
        <GlassCard className="p-4 space-y-4">
          <div className="flex justify-between items-center gap-4">
             <div className="flex-1">
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Date</label>
                <GlassInput 
                    type="date" 
                    value={date} 
                    onChange={e => setDate(e.target.value)}
                    required
                />
             </div>
             <div className="flex items-center pt-6">
                 <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={isWeekOff} onChange={e => setIsWeekOff(e.target.checked)} />
                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-blue-300 dark:peer-focus:ring-blue-800 rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600"></div>
                    <span className="ml-2 text-sm font-medium text-gray-900 dark:text-gray-300">Week Off</span>
                </label>
             </div>
          </div>

          {!isWeekOff && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300">Products</label>
                <button type="button" onClick={addItem} className="text-blue-500 text-sm font-bold flex items-center gap-1">
                    <Plus size={16} /> Add Another
                </button>
            </div>

            {items.map((item, index) => (
              <div key={item.id} className="p-3 bg-white/30 dark:bg-black/20 rounded-xl space-y-3 relative group">
                {items.length > 1 && (
                    <button 
                        type="button" 
                        onClick={() => removeItem(index)}
                        className="absolute -top-2 -right-2 p-1 bg-red-100 text-red-500 rounded-full shadow-sm hover:bg-red-200 z-10"
                    >
                        <Trash2 size={14} />
                    </button>
                )}

                {/* Searchable Input */}
                <div className="relative">
                    <div 
                        className="flex items-center justify-between w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 cursor-text"
                        onClick={() => {
                            setActiveSearchIndex(index);
                            setSearchTerm(item.productName);
                        }}
                    >
                        <span className={`${!item.productName && 'text-slate-400'}`}>{item.productName || 'Search Product / Model...'}</span>
                        <ChevronDown size={14} className="text-slate-400" />
                    </div>

                    {activeSearchIndex === index && (
                        <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-100 dark:border-gray-700 max-h-60 overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-100">
                            <div className="p-2 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50 sticky top-0">
                                <div className="flex items-center gap-2 bg-white dark:bg-black/20 rounded-lg px-2 border border-gray-200 dark:border-gray-700">
                                    <Search size={14} className="text-gray-400" />
                                    <input 
                                        autoFocus
                                        className="w-full py-2 text-sm outline-none bg-transparent"
                                        placeholder="Type model name..."
                                        value={searchTerm}
                                        onChange={e => setSearchTerm(e.target.value)}
                                    />
                                    {searchTerm && <X size={14} className="text-gray-400 cursor-pointer" onClick={() => setSearchTerm('')} />}
                                </div>
                            </div>
                            <div className="overflow-y-auto">
                                {filteredProducts.map(p => (
                                    <div 
                                        key={p} 
                                        className="px-4 py-3 text-sm hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer border-b border-gray-50 dark:border-gray-800 last:border-0"
                                        onClick={() => handleProductSelect(index, p)}
                                    >
                                        {p}
                                    </div>
                                ))}
                                {searchTerm && !filteredProducts.includes(searchTerm) && (
                                    <div 
                                        className="px-4 py-3 text-sm text-blue-600 cursor-pointer font-medium"
                                        onClick={() => handleProductSelect(index, searchTerm)}
                                    >
                                        + Add "{searchTerm}"
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                    {/* Backdrop for search */}
                    {activeSearchIndex === index && (
                        <div className="fixed inset-0 z-40 bg-transparent" onClick={() => setActiveSearchIndex(null)} />
                    )}
                </div>

                <div className="flex gap-4">
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Qty</label>
                        <input 
                            type="number"
                            min="1"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.quantity}
                            onChange={e => updateItem(index, 'quantity', parseInt(e.target.value) || 0)}
                            required
                        />
                    </div>
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Price (₹)</label>
                        <input 
                            type="number"
                            min="0"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.price}
                            onChange={e => updateItem(index, 'price', parseFloat(e.target.value) || 0)}
                            required
                        />
                    </div>
                </div>
              </div>
            ))}
          </div>
          )}
        </GlassCard>

        {/* Bill Images Section - Hide if Week Off */}
        {!isWeekOff && (
        <GlassCard className="p-4">
            <div className="flex justify-between items-center mb-4">
                <div>
                    <p className="font-medium">Bill Copies</p>
                    <p className="text-xs text-slate-500">{billImages.length} images selected</p>
                </div>
                <label className="cursor-pointer bg-slate-200 dark:bg-slate-700 px-3 py-1.5 rounded-lg text-sm font-semibold flex items-center gap-1 hover:bg-slate-300 dark:hover:bg-slate-600 transition-colors">
                    <Plus size={16} /> Add Photo
                    <input type="file" multiple accept="image/*" onChange={handleImageUpload} className="hidden" />
                </label>
            </div>

            {billImages.length === 0 ? (
                <div className="border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-6 text-center">
                    <Camera className="mx-auto text-slate-400 mb-2" size={24} />
                    <p className="text-sm text-slate-400">No bills added yet</p>
                </div>
            ) : (
                <div className="flex gap-2 overflow-x-auto pb-2 snap-x">
                    {billImages.map((img, idx) => (
                        <div key={idx} className="relative flex-shrink-0 w-24 h-24 snap-start">
                            <img src={img} alt={`Bill ${idx}`} className="w-full h-full object-cover rounded-lg border border-white/20" />
                            <button 
                                type="button"
                                onClick={() => removeImage(idx)}
                                className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 shadow-md"
                            >
                                <X size={12} />
                            </button>
                        </div>
                    ))}
                </div>
            )}
        </GlassCard>
        )}

        {!isWeekOff && (
        <GlassCard className="p-4 bg-blue-600/10 border-blue-200 dark:border-blue-900">
            <div className="flex justify-between items-center">
                <span className="text-slate-600 dark:text-slate-300">Total Value</span>
                <span className="text-2xl font-bold text-blue-600 dark:text-blue-400">₹{totalValue.toLocaleString()}</span>
            </div>
        </GlassCard>
        )}

        <GlassButton type="submit" className="w-full" disabled={isSubmitting}>
            {isSubmitting ? 'Saving...' : (isWeekOff ? 'Mark as Week Off' : 'Save Entry')}
        </GlassButton>
      </form>
    </div>

    {/* Success Modal */}
    <Modal 
        isOpen={showSuccessModal} 
        onClose={resetForm} 
        title={isWeekOff ? "Week Off Recorded" : "Entry Saved!"}
    >
        <div className="text-center space-y-6">
            <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto ${isWeekOff ? 'bg-gray-100 text-gray-500' : 'bg-green-100 text-green-600'}`}>
                {isWeekOff ? <Check size={32} /> : <Copy size={32} />}
            </div>
            <p className="text-slate-600 dark:text-slate-300">
                {isWeekOff 
                    ? `Marked ${date} as Week Off.` 
                    : `Your data has been added to the cumulative report for ${date}.`
                }
            </p>

            {!isWeekOff && (
            <div className="grid grid-cols-2 gap-4">
                <button 
                    onClick={handleShareWhatsApp}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20 transition-colors border border-[#25D366]/20"
                >
                    <Send size={24} />
                    <span className="font-bold text-sm">WhatsApp</span>
                </button>
                <button 
                    onClick={handleCopyText}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 transition-colors border border-blue-500/20"
                >
                    <Copy size={24} />
                    <span className="font-bold text-sm">Copy</span>
                </button>
            </div>
            )}

            <GlassButton onClick={resetForm} variant="secondary" className="w-full">
                Close & New Entry
            </GlassButton>
        </div>
    </Modal>
    </>
  );
};

export default NewEntry;

