      if(isWeekOff) {
          navigator.clipboard.writeText(`Name: ${user.name}\nDate: ${date}\nStatus: Week Off`);
          alert('Week Off report copied');
          return;
      }
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
