                    >
                        <Trash2 size={14} />
                    </button>
                )}

                {/* Searchable Input */}
                <div className="relative">
                    <div 
                        className="flex items-center justify-between w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 cursor-text"
