                    </div>

                    {activeSearchIndex === index && (
                        <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-100 dark:border-gray-700 max-h-60 overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-100">
