                                        value={searchTerm}
                                        onChange={e => setSearchTerm(e.target.value)}
                                    />
                                    {searchTerm && <X size={14} className="text-gray-400 cursor-pointer" onClick={() => setSearchTerm('')} />}
                                </div>
                            </div>
                            <div className="overflow-y-auto">
                                {filteredProducts.map(p => (
                                    <div 
                                        key={p} 
                                        className="px-4 py-3 text-sm hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer border-b border-gray-50 dark:border-gray-800 last:border-0"
