                                {searchTerm && !filteredProducts.includes(searchTerm) && (
                                    <div 
                                        className="px-4 py-3 text-sm text-blue-600 cursor-pointer font-medium"
                                        onClick={() => handleProductSelect(index, searchTerm)}
