                </div>

                <div className="flex gap-4">
                    <div className="flex-1">
                        <label className="text-[10px] uppercase text-slate-400 font-bold">Qty</label>
                        <input 
                            type="number"
                            min="1"
                            className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 pb-1 focus:border-blue-500 outline-none font-mono text-lg"
                            value={item.quantity}
                            onChange={e => updateItem(index, 'quantity', parseInt(e.target.value) || 0)}
                            required
                        />
                    </div>
                    <div className="flex-[1.5]">
                        <div className="flex justify-between items-end">
                            <label className="text-[10px] uppercase text-slate-400 font-bold">
                                {inputModes[index] === 'total' ? 'Total (₹)' : 'Unit Price (₹)'}
                            </label>
                            <button 
                                type="button" 
                                onClick={() => togglePriceMode(index)}
                                className={`text-[10px] px-2 py-0.5 rounded-full mb-1 border transition-colors ${inputModes[index] === 'total' ? 'bg-blue-100 text-blue-600 border-blue-200' : 'bg-gray-100 text-gray-500 border-gray-200'}`}
