        {!isWeekOff && (
        <GlassCard className="p-4 bg-blue-600/10 border-blue-200 dark:border-blue-900">
            <div className="flex justify-between items-center">
                <span className="text-slate-600 dark:text-slate-300">Total Value</span>
                <span className="text-2xl font-bold text-blue-600 dark:text-blue-400">₹{totalValue.toLocaleString()}</span>
            </div>
        </GlassCard>
        )}

        <GlassButton type="submit" className="w-full" disabled={isSubmitting}>
            {isSubmitting ? 'Saving...' : (isWeekOff ? 'Mark as Week Off' : 'Save Entry')}
        </GlassButton>
      </form>
    </div>

    {/* Success Modal */}
    <Modal 
        isOpen={showSuccessModal} 
        onClose={resetForm} 
        title={isWeekOff ? "Week Off Recorded" : "Entry Saved!"}
    >
        <div className="text-center space-y-6">
            <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto ${isWeekOff ? 'bg-gray-100 text-gray-500' : 'bg-green-100 text-green-600'}`}>
